// Relation attaches a declared one-to-one child query. The manifest resolves
// the relation name from the parent and child entities.
func (q *ProjectQuery) Relation(child any) *ProjectQuery {
	q.q.Req.Err = &ir.Error{Code: "RELATION_UNKNOWN", Msg: "relation target or key selection is not declared"}
	return q
}
func (q *ProjectQuery) Relations(child any) *ProjectQuery {
	if c, ok := child.(*AccountQuery); ok {
		if c.q.LinkLeft != "" && (c.q.LinkLeft != "seq" || c.q.LinkRight != "seq") {
			q.q.Req.Err = &ir.Error{Code: "RELATION_UNKNOWN", Msg: "link selection does not match relation"}
			return q
		}
		q.q.Relation("accounts", c.q)
		return q
	}
	q.q.Req.Err = &ir.Error{Code: "RELATION_UNKNOWN", Msg: "relation target or key selection is not declared"}
	return q
}
func (q *ProjectQuery) Join(child any) *ProjectQuery     { return q.joinTarget(child, "inner") }
func (q *ProjectQuery) LeftJoin(child any) *ProjectQuery { return q.joinTarget(child, "left") }
func (q *ProjectQuery) joinTarget(child any, kind string) *ProjectQuery {
	if c, ok := child.(*AccountQuery); ok {
		if c.q.LinkLeft != "" && (c.q.LinkLeft != "seq" || c.q.LinkRight != "seq") {
			q.q.Req.Err = &ir.Error{Code: "RELATION_UNKNOWN", Msg: "link selection does not match relation"}
			return q
		}
		q.q.Join("accounts", kind, c.q)
		return q
	}
	q.q.Req.Err = &ir.Error{Code: "RELATION_UNKNOWN", Msg: "relation target or key selection is not declared"}
	return q
}

