// Terminals.
func (q *ProjectQuery) Get() (*ProjectRow, error) {
	row, err := q.GetOrNil()
	if err != nil {
		return nil, err
	}
	if row == nil {
		return nil, orm.ErrNoRows
	}
	return row, nil
}

// GetOrNil returns nil, nil when the query has no row.
func (q *ProjectQuery) GetOrNil() (*ProjectRow, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "one"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsProjectDirect, scanProjectDirect); used {
		if err != nil || len(direct) == 0 {
			return nil, err
		}
		return direct[0], nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil || len(rows.Data) == 0 {
		return nil, err
	}
	return scanProject(rows.Data[0], rows.Assemble, rows), nil
}

func (q *ProjectQuery) Gets() (*orm.Collection[ProjectRow], error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	if direct, used, err := orm.QueryDirect(ctx, ex, q.q.Req, acceptsProjectDirect, scanProjectDirect); used {
		if err != nil {
			return nil, err
		}
		return collectProjectDirect(direct, q.keyFn), nil
	}
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	return collectProject(rows, q.keyFn), nil
}

// Stream visits independently owned rows without accumulating the complete result.
// Returning false stops the query and closes its database cursor.
func (q *ProjectQuery) Stream(visit func(*ProjectRow) bool) (orm.StreamResult, error) {
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return orm.StreamResult{}, err
	}
	if visit == nil {
		return orm.StreamResult{}, &ir.Error{Code: orm.CodeIrInvalid, Msg: "stream visitor is required"}
	}
	q.q.Req.IR.Kind = "all"
	return orm.Stream(ctx, ex, q.q.Req, func(vals []any, rows *orm.Rows) bool {
		return visit(scanProject(vals, rows.Assemble, rows))
	})
}

// GetsBySeq applies seq = v and runs the collection terminal.
func (q *ProjectQuery) GetsBySeq(v int64) (*orm.Collection[ProjectRow], error) {
	return q.Seq(v).Gets()
}

// GetsByName applies name = v and runs the collection terminal.
func (q *ProjectQuery) GetsByName(v string) (*orm.Collection[ProjectRow], error) {
	return q.Name(v).Gets()
}

func collectProject(rows *orm.Rows, keyFn func(*ProjectRow) orm.Key) *orm.Collection[ProjectRow] {
	c := orm.NewCollection[ProjectRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanProject(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectProjectDirect(rows []*ProjectRow, keyFn func(*ProjectRow) orm.Key) *orm.Collection[ProjectRow] {
	c := orm.NewCollection[ProjectRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.Seq}), r)
		}
	}
	return c
}

// GetsAfter reads the next keyset page. An empty cursor starts at the first row.
func (q *ProjectQuery) GetsAfter(cursor string, per int) (*orm.KeysetPage[ProjectRow], error) {
	if err := q.q.Keyset("after", cursor, per, []string{"seq"}); err != nil {
		return nil, err
	}
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	items := collectProject(rows, q.keyFn)
	return orm.KeysetPageFromRows(rows, items, q.q.Req.IR.Order)
}

// GetsBefore reads the previous keyset page and restores the requested order.
func (q *ProjectQuery) GetsBefore(cursor string, per int) (*orm.KeysetPage[ProjectRow], error) {
	if err := q.q.Keyset("before", cursor, per, []string{"seq"}); err != nil {
		return nil, err
	}
	ctx, ex, err := q.binding.Resolve()
	if err != nil {
		return nil, err
	}
	q.q.Req.IR.Kind = "all"
	rows, err := orm.Query(ctx, ex, q.q.Req)
	if err != nil {
		return nil, err
	}
	orm.ReverseRows(rows)
	items := collectProject(rows, q.keyFn)
	return orm.KeysetPageFromRows(rows, items, q.q.Req.IR.Order)
}

